import DashboardIcon from "@mui/icons-material/Dashboard";
import WalletIcon from "@mui/icons-material/Wallet";
import CategoryIcon from "@mui/icons-material/Category";
import InventoryIcon from "@mui/icons-material/Inventory";
import ShoppingCartIcon from "@mui/icons-material/ShoppingCart";
import AccountCircle from "@mui/icons-material/AccountCircle";
import LogoutIcon from "@mui/icons-material/Logout";
import AssignmentIcon from "@mui/icons-material/Assignment";
import MenuBookIcon from "@mui/icons-material/MenuBook";
import Wallet from "./StoreRoutes/SellerWallet";
import DashBoard from "./StoreRoutes/DashBoard";
import StoreCategories from "./StoreRoutes/Categories";
import FoodCategory from "./StoreRoutes/FoodCategory/FoodCategory";
import SellerProduct from "./StoreRoutes/SellerProduct";
import MenuCards from "./StoreRoutes/MenuCards";
import Stock from "./StoreRoutes/Stock";
import Profile from "./StoreRoutes/Profile";
import CouponManagement from "./StoreRoutes/coupon";
import StoreOrder from "./StoreRoutes/StoreOrder";
import DiscountIcon from "@mui/icons-material/Discount";
import { isFoodSellerFromStorage } from "utils/sellerType";

const StoreRoutes = (isFoodSeller = isFoodSellerFromStorage()) => [
  {
    type: "collapse",
    name: "Dashboard",
    key: "dashboard1",
    icon: <DashboardIcon />,
    route: "/dashboard1",
    component: <DashBoard />,
  },
  {
    type: "collapse",
    name: "Profile",
    key: "profile",
    icon: <AccountCircle />,
    route: "/profile",
    component: <Profile />,
  },
  {
    type: "collapse",
    name: "Wallet",
    key: "Wallet",
    icon: <WalletIcon />,
    route: "/Wallet",
    component: <Wallet />,
  },
  {
    type: "collapse",
    name: "Categories",
    key: "categories",
    icon: <CategoryIcon />,

    route: isFoodSeller
    ? "/food-category"
    : "/storecat",

    component:
      isFoodSeller ? (
        <FoodCategory />
      ) : (
        <StoreCategories />
      ),
  },
  {
    type: "collapse",
    name: "Products",
    key: "products",
    icon: <InventoryIcon />,
    route: "/sellerProduct",
    component: <SellerProduct />,
  },
  {
    type: "collapse",
    name: "Menu Cards",
    key: "menu-cards",
    icon: <MenuBookIcon />,
    route: "/menu-cards",
    component: <MenuCards />,
  },
  {
    type: "collapse",
    name: "Stock",
    key: "stock",
    icon: <AssignmentIcon />,
    route: "/stock",
    component: <Stock />,
  },
  {
    type: "collapse",
    name: "Orders",
    key: "orders",
    icon: <ShoppingCartIcon />,
    route: "/store-orders",
    component: <StoreOrder />,
  },
  {
    type: "collapse",
    name: "Offers",
    key: "offers",
    icon: <DiscountIcon />,
    route: "/offers",
    component: <CouponManagement />,
  },
  {
    type: "collapse",
    name: "Log-Out",
    key: "logout",
    icon: <LogoutIcon />,
    route: "#",
  },
];

export default StoreRoutes;
